// Normalize all source data into a standard job schema
const today = new Date().toISOString().split('T')[0];
const results = [];

for (const item of $input.all()) {
  const source = item.json._source || 'unknown';
  const d = item.json;
  let jobs = [];

  // --- RemoteOK ---
  if (source === 'remoteok') {
    const raw = Array.isArray(d) ? d.slice(1) : (Array.isArray(d.body) ? d.body.slice(1) : []);
    for (const j of raw) {
      if (!j || !j.position) continue;
      jobs.push({
        job_title: j.position || '',
        company: j.company || '',
        job_url: j.url || `https://remoteok.com/remote-jobs/${j.id}`,
        location_text: j.location || 'Remote Worldwide',
        salary: j.salary_min ? `$${j.salary_min}–$${j.salary_max}/yr` : '',
        description: (j.description || '').replace(/<[^>]+>/g, ' ').trim(),
        posted_date: j.date || '',
        tags: Array.isArray(j.tags) ? j.tags : []
      });
    }
  }

  // --- Remotive ---
  else if (source === 'remotive') {
    const raw = d.jobs || (Array.isArray(d) ? d : []);
    for (const j of raw) {
      if (!j || !j.title) continue;
      jobs.push({
        job_title: j.title || '',
        company: j.company_name || '',
        job_url: j.url || '',
        location_text: j.candidate_required_location || 'Worldwide',
        salary: j.salary || '',
        description: (j.description || '').replace(/<[^>]+>/g, ' ').trim(),
        posted_date: j.publication_date || '',
        tags: Array.isArray(j.tags) ? j.tags : (j.job_type ? [j.job_type] : [])
      });
    }
  }

  // --- We Work Remotely (RSS) ---
  else if (source === 'weworkremotely') {
    const raw = Array.isArray(d) ? d : [d];
    for (const j of raw) {
      if (!j || !j.title) continue;
      jobs.push({
        job_title: j.title || '',
        company: j.author || '',
        job_url: j.link || j.id || '',
        location_text: 'Remote',
        salary: '',
        description: (j.content || j.summary || j.contentSnippet || '').replace(/<[^>]+>/g, ' ').trim(),
        posted_date: j.pubDate || j.isoDate || '',
        tags: []
      });
    }
  }

  // --- Himalayas ---
  else if (source === 'himalayas') {
    const raw = d.jobs || (Array.isArray(d) ? d : []);
    for (const j of raw) {
      if (!j || !j.title) continue;
      const loc = Array.isArray(j.locationRestrictions) ? j.locationRestrictions.join(', ') : 'Worldwide';
      const salMin = j.minAnnualSalary || j.min_salary || 0;
      const salMax = j.maxAnnualSalary || j.max_salary || 0;
      jobs.push({
        job_title: j.title || '',
        company: (j.company && j.company.name) ? j.company.name : (j.companyName || ''),
        job_url: j.applicationLink || j.url || `https://himalayas.app/jobs/${j.slug || j.id}`,
        location_text: loc,
        salary: salMin ? `$${salMin.toLocaleString()}–$${salMax.toLocaleString()}/yr` : '',
        description: (j.description || j.responsibilities || '').replace(/<[^>]+>/g, ' ').trim(),
        posted_date: j.createdAt || j.created_at || '',
        tags: Array.isArray(j.tags) ? j.tags : []
      });
    }
  }

  // --- Dynamite Jobs (RSS) ---
  else if (source === 'dynamite') {
    const raw = Array.isArray(d) ? d : [d];
    for (const j of raw) {
      if (!j || !j.title) continue;
      jobs.push({
        job_title: j.title || '',
        company: j.author || j.creator || '',
        job_url: j.link || j.id || '',
        location_text: 'Remote Worldwide',
        salary: '',
        description: (j.content || j.summary || j.contentSnippet || '').replace(/<[^>]+>/g, ' ').trim(),
        posted_date: j.pubDate || j.isoDate || '',
        tags: []
      });
    }
  }

  // --- YC Work at a Startup ---
  else if (source === 'yc') {
    const raw = d.jobs || (Array.isArray(d) ? d : []);
    for (const j of raw) {
      if (!j || !(j.title || j.job_title)) continue;
      jobs.push({
        job_title: j.title || j.job_title || '',
        company: (j.company && (j.company.name || j.company.company_name)) || j.company_name || '',
        job_url: j.url || j.job_url || `https://www.workatastartup.com/jobs/${j.id}`,
        location_text: j.location || 'Remote',
        salary: j.salary || '',
        description: (j.description || j.body || '').replace(/<[^>]+>/g, ' ').trim(),
        posted_date: j.created_at || j.posted_at || '',
        tags: Array.isArray(j.tags) ? j.tags : []
      });
    }
  }

  // --- Wellfound / AngelList ---
  else if (source === 'wellfound') {
    const raw = d.jobs || d.data || (Array.isArray(d) ? d : []);
    for (const j of raw) {
      if (!j || !(j.title || j.job_title)) continue;
      jobs.push({
        job_title: j.title || j.job_title || '',
        company: (j.startup && j.startup.name) || j.company || '',
        job_url: j.url || j.job_url || '',
        location_text: j.remote ? 'Remote' : (j.location || 'Remote'),
        salary: j.compensation || j.salary || '',
        description: (j.description || '').replace(/<[^>]+>/g, ' ').trim(),
        posted_date: j.created_at || '',
        tags: Array.isArray(j.tags) ? j.tags : []
      });
    }
  }

  // --- Otta ---
  else if (source === 'otta') {
    const raw = d.jobs || d.data || (Array.isArray(d) ? d : []);
    for (const j of raw) {
      if (!j || !j.title) continue;
      jobs.push({
        job_title: j.title || '',
        company: (j.company && j.company.name) || j.company_name || '',
        job_url: j.url || `https://app.otta.com/jobs/${j.externalId || j.id}`,
        location_text: j.remote ? 'Remote Worldwide' : (j.location || 'Remote'),
        salary: j.salary || (j.min_salary ? `$${j.min_salary}–$${j.max_salary}/yr` : ''),
        description: (j.description || j.jobDescription || '').replace(/<[^>]+>/g, ' ').trim(),
        posted_date: j.created_at || j.published_at || '',
        tags: Array.isArray(j.skills) ? j.skills.map(s => s.value || s) : []
      });
    }
  }

  // Add normalized jobs to results
  for (const job of jobs) {
    if (!job.job_title || !job.job_url) continue;
    results.push({
      json: {
        date_found: today,
        source: source,
        job_title: job.job_title,
        company: job.company,
        job_url: job.job_url,
        location_text: job.location_text,
        salary: job.salary,
        description: job.description.slice(0, 3000),
        posted_date: job.posted_date,
        tags: job.tags,
        job_id: job.job_url || `${job.company}-${job.job_title}`.toLowerCase().replace(/\s+/g, '-')
      }
    });
  }
}

return results;

// Keep only jobs matching target keywords
const keywords = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote',
  'work from anywhere', 'remote data analyst', 'remote data scientist',
  'remote ai marketing', 'remote marketing analyst', 'remote growth analyst',
  'remote bi analyst', 'remote automation', 'remote ai workflow',
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst',
  'marketing analyst', 'performance marketing', 'growth analyst',
  'ai marketing', 'ai automation', 'ai workflow', 'martech', 'marketing data',
  'analytics engineer', 'growth hacker', 'digital marketing analyst',
  'seo analyst', 'ppc analyst', 'paid media', 'marketing operations',
  'data analytics', 'product analytics', 'revenue operations',
  'customer analytics', 'attribution analyst', 'web analyst', 'ga4',
  'tableau', 'power bi', 'looker', 'dbt', 'python analyst', 'sql analyst'
];

const results = [];
for (const item of $input.all()) {
  const job = item.json;
  const searchText = [
    job.job_title, job.description,
    Array.isArray(job.tags) ? job.tags.join(' ') : ''
  ].join(' ').toLowerCase();

  const matched = keywords.some(kw => searchText.includes(kw.toLowerCase()));
  if (matched) results.push(item);
}

return results;

// Remove duplicate URLs within current batch
const seen = new Set();
const results = [];

for (const item of $input.all()) {
  const url = (item.json.job_url || '').toLowerCase().trim();
  const key = `${(item.json.company || '').toLowerCase()}::${(item.json.job_title || '').toLowerCase()}`;

  if (!url || seen.has(url) || seen.has(key)) continue;

  seen.add(url);
  seen.add(key);
  results.push(item);
}

return results;

// Hard filter: reject jobs that cannot be done from Taiwan
const REJECT_PHRASES = [
  'us only', 'usa only', 'united states only', 'us residents only', 'us citizens only',
  'must be a us', 'must be authorized to work in the us', 'us work authorization',
  'canada only', 'canadian only', 'uk only', 'united kingdom only',
  'eu only', 'europe only', 'european union only', 'must be based in europe',
  'australia only', 'australian only', 'new zealand only',
  'must be based in', 'must live in', 'must reside in',
  'must be authorized to work in', 'local work permit required',
  'work authorization required', 'right to work in',
  'hybrid', 'on-site only', 'onsite only', 'in-office', 'office required',
  'no remote', 'not remote', 'remote not available',
  'fixed us hours', 'fixed est hours', 'fixed pst hours',
  'fixed cet hours', 'fixed gmt hours', 'us business hours required',
  'must work eastern time', 'must be available 9am-5pm est',
  'not available in taiwan', 'not hiring in asia',
  'remote within us', 'us remote only', 'domestic us remote'
];

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = [
    job.job_title, job.description, job.location_text,
    Array.isArray(job.tags) ? job.tags.join(' ') : ''
  ].join(' ').toLowerCase();

  const hardReject = REJECT_PHRASES.some(phrase => text.includes(phrase));

  if (!hardReject) {
    results.push(item);
  }
}

return results;

// Parse the AI JSON response and merge back with job data
const results = [];

for (const item of $input.all()) {
  const job = item.json;
  // The OpenAI node returns the completion in message.content or choices[0].message.content
  const rawContent = job.message?.content
    || (job.choices && job.choices[0]?.message?.content)
    || job.content
    || job.text
    || '';

  let aiResult = {};
  try {
    // Extract JSON even if there's extra whitespace or markdown
    const jsonMatch = rawContent.match(/\{[\s\S]*\}/);
    if (jsonMatch) aiResult = JSON.parse(jsonMatch[0]);
  } catch (e) {
    aiResult = {
      taiwan_eligible: 'unclear',
      reason: 'Parse error',
      location_risk: 'medium',
      timezone_risk: 'medium',
      contractor_possible: 'unclear',
      decision: 'manual_check'
    };
  }

  // Reject jobs where AI says clearly no
  if (aiResult.decision === 'reject' || aiResult.taiwan_eligible === 'no') {
    continue;
  }

  // Carry original job data forward with AI results attached
  results.push({
    json: {
      ...job,
      _ai: aiResult
    }
  });
}

return results;

// Score async culture and filter out sync-only jobs
const ASYNC_POSITIVE = [
  'async', 'asynchronous', 'flexible hours', 'flexible schedule',
  'distributed team', 'remote first', 'remote-first',
  'low meeting', 'documentation first', 'written communication',
  'results oriented', 'outcome based', 'set your own hours',
  'work when you want', 'flexible working', 'no core hours',
  'all time zones', 'time zone flexible', 'work across time zones'
];

const ASYNC_NEGATIVE = [
  'strict 9 to 5', 'fixed us hours', 'fixed est hours', 'fixed pst hours',
  'fixed cet hours', 'daily live calls required', 'must overlap full business day',
  'must be available during us hours', 'core hours 9am-5pm est',
  'must work eastern time', 'real-time collaboration required',
  'synchronous team', '9-5 schedule required'
];

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = [
    job.job_title, job.description,
    Array.isArray(job.tags) ? job.tags.join(' ') : ''
  ].join(' ').toLowerCase();

  const hasNegative = ASYNC_NEGATIVE.some(p => text.includes(p));
  if (hasNegative) continue;

  const positiveCount = ASYNC_POSITIVE.filter(p => text.includes(p)).length;
  const asyncLevel = positiveCount >= 3 ? 'high' : positiveCount >= 1 ? 'medium' : 'low';
  const asyncSignals = ASYNC_POSITIVE.filter(p => text.includes(p));

  results.push({
    json: {
      ...job,
      _async_level: asyncLevel,
      _async_signals: asyncSignals
    }
  });
}

return results;

// Filter by role relevance and tag match level
const PRIMARY_ROLES = [
  'data analyst', 'data scientist', 'junior data scientist', 'senior data analyst',
  'business intelligence analyst', 'bi analyst', 'bi developer',
  'marketing analyst', 'performance marketing analyst', 'growth analyst',
  'ai marketing specialist', 'ai automation specialist', 'ai workflow consultant',
  'martech analyst', 'marketing data analyst', 'analytics engineer',
  'digital marketing analyst', 'seo analyst', 'ppc specialist',
  'paid media analyst', 'marketing scientist', 'growth hacker',
  'attribution analyst', 'web analyst', 'product analyst'
];

const ADJACENT_ROLES = [
  'data engineer', 'revenue analyst', 'sales analyst', 'operations analyst',
  'financial analyst', 'research analyst', 'digital marketing manager',
  'content analyst', 'social media analyst', 'automation engineer',
  'workflow automation', 'ai specialist', 'machine learning engineer',
  'no-code developer', 'crm analyst', 'email marketing analyst',
  'ecommerce analyst', 'campaign analyst', 'demand gen analyst'
];

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const titleLower = (job.job_title || '').toLowerCase();
  const textLower = [
    job.job_title, job.description,
    Array.isArray(job.tags) ? job.tags.join(' ') : ''
  ].join(' ').toLowerCase();

  const primaryMatch = PRIMARY_ROLES.find(r => titleLower.includes(r) || textLower.includes(r));
  const adjacentMatch = ADJACENT_ROLES.find(r => textLower.includes(r));

  if (!primaryMatch && !adjacentMatch) continue;

  results.push({
    json: {
      ...job,
      _role_match: primaryMatch ? 'primary' : 'adjacent',
      _role_category: primaryMatch || adjacentMatch
    }
  });
}

return results;

// Score each job 0-100 across 4 dimensions
const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const ai = job._ai || {};
  let score = 0;
  const breakdown = {};

  const text = [
    job.job_title, job.description, job.location_text,
    Array.isArray(job.tags) ? job.tags.join(' ') : ''
  ].join(' ').toLowerCase();

  // === Taiwan Eligibility (max 40 pts) ===
  const te = ai.taiwan_eligible || 'unclear';
  const lr = ai.location_risk || 'medium';
  const isContractorFriendly = [
    'worldwide', 'work from anywhere', 'global remote', 'contractor',
    'deel', 'remote.com', 'oyster', 'eor', 'b2b', 'freelance'
  ].some(kw => text.includes(kw));
  const isApac = text.includes('apac');

  if (te === 'yes' && lr === 'low') {
    if (isContractorFriendly) { score += 40; breakdown.taiwan = 40; }
    else if (isApac) { score += 30; breakdown.taiwan = 30; }
    else { score += 25; breakdown.taiwan = 25; }
  } else if (te === 'unclear' || lr === 'medium') {
    if (isContractorFriendly) { score += 25; breakdown.taiwan = 25; }
    else { score += 20; breakdown.taiwan = 20; }
  } else {
    breakdown.taiwan = 0;
  }

  // === Async Fit (max 25 pts) ===
  const asyncLevel = job._async_level || 'low';
  const asyncSigs = (job._async_signals || []).length;
  if (asyncLevel === 'high' || asyncSigs >= 3) { score += 25; breakdown.async = 25; }
  else if (asyncLevel === 'medium' || asyncSigs >= 1) { score += 20; breakdown.async = 20; }
  else if (text.includes('distributed') || text.includes('remote first')) { score += 15; breakdown.async = 15; }
  else if (text.includes('remote')) { score += 10; breakdown.async = 10; }
  else { breakdown.async = 0; }

  // === Role Fit (max 25 pts) ===
  const roleMatch = job._role_match || 'none';
  if (roleMatch === 'primary') { score += 25; breakdown.role = 25; }
  else if (roleMatch === 'adjacent') { score += 15; breakdown.role = 15; }
  else { breakdown.role = 0; }

  // === Salary Fit (max 25 pts) ===
  const salaryText = (job.salary || '').replace(/,/g, '');
  const numMatch = salaryText.match(/(\d+)/);
  if (numMatch) {
    const n = parseInt(numMatch[1]);
    // Detect if monthly (~1k-20k range) vs annual (~30k-300k range)
    const isMonthly = n < 25000;
    const monthly = isMonthly ? n : Math.round(n / 12);
    if (monthly >= 5000) { score += 25; breakdown.salary = 25; }
    else if (monthly >= 3000) { score += 15; breakdown.salary = 15; }
    else { score += 10; breakdown.salary = 10; }
  } else {
    breakdown.salary = 0;
  }

  score = Math.min(score, 100);

  // === Determine decision ===
  let decision;
  if (te === 'yes' && score >= 85 && (ai.location_risk === 'low') && (ai.timezone_risk === 'low' || ai.timezone_risk === 'medium')) {
    decision = 'apply_immediately';
  } else if ((te === 'unclear' || ai.location_risk === 'medium') && score >= 85) {
    decision = 'manual_check';
  } else if (te === 'no' || ai.location_risk === 'high' || score < 70) {
    decision = 'reject';
  } else {
    decision = 'keep';
  }

  // === Why good fit ===
  const reasons = [];
  if (te === 'yes') reasons.push('Taiwan eligible');
  if (asyncLevel === 'high') reasons.push('Strong async culture');
  if (roleMatch === 'primary') reasons.push(`Great role match: ${job._role_category}`);
  if (ai.contractor_possible === 'yes') reasons.push('Contractor arrangement possible');
  if (job.salary) reasons.push(`Salary listed`);
  if (isApac) reasons.push('APAC-friendly');
  const whyGoodFit = reasons.join(' | ') || 'Passed Taiwan + role filters';

  results.push({
    json: {
      ...job,
      _score: score,
      _score_breakdown: breakdown,
      _decision: decision,
      _why_good_fit: whyGoodFit,
      taiwan_eligible: ai.taiwan_eligible || 'unclear',
      taiwan_reason: ai.reason || '',
      location_risk: ai.location_risk || 'medium',
      timezone_risk: ai.timezone_risk || 'medium',
      contractor_possible: ai.contractor_possible || 'unclear',
      async_level: job._async_level || 'low',
      role_category: job._role_category || '',
      why_good_fit: whyGoodFit
    }
  });
}

return results;

// Split aggregated jobs back to individual items for routing
const agg = $input.first();
const jobs = agg.json.jobs || [];
if (!Array.isArray(jobs) || jobs.length === 0) return [];
return jobs.map(j => ({ json: j }));

// Build the daily digest email from the aggregated scored jobs
const agg = $input.first();
const allJobs = agg.json.jobs || [];

const today = new Date().toLocaleDateString('en-US', {
  timeZone: 'Asia/Taipei',
  year: 'numeric', month: 'long', day: 'numeric'
});

// Sort by score descending
const sorted = [...allJobs].sort((a, b) => (b._score || 0) - (a._score || 0));
const topJobs = sorted.filter(j => (j._score || 0) >= 70).slice(0, 10);
const manualCheck = sorted.filter(j => j.taiwan_eligible === 'unclear' && (j._score || 0) >= 70);
const instantAlert = sorted.filter(j => (j._score || 0) >= 85);

// Rejection stats
const total = allJobs.length;
const kept = topJobs.length;

let html = `<h2>🌏 Daily Taiwan Eligible Async Remote Jobs — ${today}</h2>`;
html += `<p><strong>${kept}</strong> qualified jobs found today. ${instantAlert.length > 0 ? `<strong style="color:#16a34a">⚡ ${instantAlert.length} jobs scored 85+ — apply immediately!</strong>` : ''}</p>`;
html += '<hr>';

if (topJobs.length > 0) {
  html += '<h3>Top Jobs Today</h3>';
  topJobs.forEach((job, i) => {
    const scoreColor = (job._score || 0) >= 85 ? '#16a34a' : (job._score || 0) >= 70 ? '#d97706' : '#6b7280';
    html += `<div style="margin-bottom:24px;padding:16px;border:1px solid #e5e7eb;border-radius:8px;">`;
    html += `<h4 style="margin:0 0 8px">${i + 1}. <a href="${job.job_url}">${job.job_title}</a></h4>`;
    html += `<table style="font-size:14px;border-collapse:collapse;width:100%">`;
    html += `<tr><td style="color:#6b7280;padding:2px 8px 2px 0">Company</td><td>${job.company}</td></tr>`;
    html += `<tr><td style="color:#6b7280;padding:2px 8px 2px 0">Score</td><td><strong style="color:${scoreColor}">${job._score}/100</strong></td></tr>`;
    html += `<tr><td style="color:#6b7280;padding:2px 8px 2px 0">Taiwan Eligible</td><td>${job.taiwan_eligible}</td></tr>`;
    html += `<tr><td style="color:#6b7280;padding:2px 8px 2px 0">Reason</td><td>${job.taiwan_reason || 'N/A'}</td></tr>`;
    html += `<tr><td style="color:#6b7280;padding:2px 8px 2px 0">Async Level</td><td>${job.async_level || 'unknown'}</td></tr>`;
    html += `<tr><td style="color:#6b7280;padding:2px 8px 2px 0">Timezone Risk</td><td>${job.timezone_risk || 'unknown'}</td></tr>`;
    html += `<tr><td style="color:#6b7280;padding:2px 8px 2px 0">Salary</td><td>${job.salary || 'Not listed'}</td></tr>`;
    html += `<tr><td style="color:#6b7280;padding:2px 8px 2px 0">Why Good Fit</td><td>${job.why_good_fit || 'Passed filters'}</td></tr>`;
    html += `</table>`;
    html += `<p style="margin:8px 0 0"><a href="${job.job_url}" style="background:#6366f1;color:#fff;padding:6px 14px;border-radius:4px;text-decoration:none;font-size:13px">Apply Now →</a></p>`;
    html += `</div>`;
  });
} else {
  html += '<p>No jobs scored 70+ today. The world keeps turning — try again tomorrow.</p>';
}

if (manualCheck.length > 0) {
  html += '<hr><h3>⚠️ Manual Check Required (unclear eligibility, high score)</h3><ul>';
  manualCheck.slice(0, 5).forEach(job => {
    html += `<li><a href="${job.job_url}">${job.job_title}</a> at <strong>${job.company}</strong> — Score: ${job._score} — ${job.taiwan_reason || 'Unclear eligibility'}</li>`;
  });
  html += '</ul>';
}

html += '<hr><h3>📊 Today\'s Summary</h3><table style="font-size:14px">';
html += `<tr><td>Total raw jobs found</td><td>${total}</td></tr>`;
html += `<tr><td>Passed all filters (≥70)</td><td>${sorted.filter(j => (j._score||0)>=70).length}</td></tr>`;
html += `<tr><td>Instant apply (≥85)</td><td>${instantAlert.length}</td></tr>`;
html += `<tr><td>Manual check</td><td>${manualCheck.length}</td></tr>`;
html += `<tr><td>Rejected (below 70)</td><td>${sorted.filter(j => (j._score||0)<70).length}</td></tr>`;
html += '</table>';

const subject = instantAlert.length > 0
  ? `⚡ ${instantAlert.length} HIGH-SCORE async remote jobs today — apply now!`
  : `🌏 ${kept} Taiwan-eligible async remote jobs — ${today}`;

return [{ json: { subject, html, jobCount: kept, instantAlertCount: instantAlert.length } }];
